configuration.tbelDecoder:
// Parse difensivo iniziale
var raw = decodeToJson(payload);
if (!raw) return null;

var data = raw.payload ? raw.payload : raw;
var hw = data.hw || {};
var analysis = data.analysis || {};

// Costruzione forzata di sole chiavi 'flat' (tipi primitivi)
var cleanTelemetry = {
    spore_count: Number(analysis.spore_count || 0),
    detected: analysis.detected ? 1 : 0,
    frame_id: Number(data.frame_id || 0),
    sample_id: String(data.sample_id || ""),
    
    // Diagnostic HW
    cpu_temp_c: Number(hw.cpu_temp_c || 0),
    processing_time_s: Number(hw.processing_time_s || 0),
    ram_used_percent: hw.ram ? Number(hw.ram.used_percent) : 0,
    disk_used_percent: hw.disk ? Number(hw.disk.used_percent) : 0
};

return {
   deviceName: String(data.device_id || "sensore_001"),
   deviceType: "Optical Biosensor",
   telemetry: cleanTelemetry
};
